export function media(slug: string, key: string): Media | undefined {
  return MEDIA[slug]?.[key];
}

export function gallery(slug: string, keys: string[]): Media[] {
  return keys.map((k) => media(slug, k)).filter((m): m is Media => Boolean(m));
}